fn main() {
    // ---- Move semantics in detail ----

    // 1. Assignment moves
    let s1 = String::from("hello");
    let s2 = s1;  // s1 is moved to s2
    // s1 is now invalid

    // 2. Passing to functions moves
    let s3 = String::from("world");
    take_ownership(s3);  // s3 is moved
    // s3 is now invalid

    // 3. Returning from functions moves
    let s4 = give_ownership();  // ownership moves from function to s4

    // 4. Functions that take ownership and return it
    let s5 = String::from("hello");
    let s6 = take_and_return(s5);  // s5 is moved in, s6 is moved out

    // ---- Copy types (not moved) ----
    let x = 5;
    let y = x;  // x is copied, not moved
    println!("x: {}, y: {}", x, y);

    // ---- Move with tuples ----
    let tuple1 = (String::from("hello"), 42);
    let tuple2 = tuple1;  // tuple1 is moved
    // println!("{:?}", tuple1);  // ERROR!

    // ---- Move with arrays ----
    let arr1 = [String::from("a"), String::from("b")];
    let arr2 = arr1;  // arr1 is moved
    // println!("{:?}", arr1);  // ERROR!
}

fn take_ownership(s: String) {
    println!("take_ownership: {}", s);
}  // s is dropped here

fn give_ownership() -> String {
    let s = String::from("returned");
    s  // ownership moves to caller
}

fn take_and_return(s: String) -> String {
    println!("take_and_return: {}", s);
    s  // ownership moves back to caller
}

fn main2() {
    // ---- Move vs Copy: The difference ----

    // Copy types (implement the Copy trait)
    let a: i32 = 5;
    let b = a;  // Copy
    println!("a: {}, b: {}", a, b);  // Both valid

    // Move types (do NOT implement Copy)
    let c = String::from("hello");
    let d = c;  // Move
    // println!("c: {}", c);  // ERROR!

    // ---- What types are Copy? ----
    // All integers: i8, i16, i32, i64, i128, isize
    // All unsigned integers: u8, u16, u32, u64, u128, usize
    // Floating point: f32, f64
    // Boolean: bool
    // Character: char
    // Tuples of Copy types: (i32, i32) is Copy
    // Tuples with non-Copy types: NOT Copy
}

